import '../../profile/domain/profile.dart';

/// Phone OTP login against the existing backend endpoints. The OTP is generated by the
/// backend and delivered by the Android SMS gateway; the app only forwards what the user typed.
abstract interface class AuthRepository {
  /// Normalizes [phone] and asks the backend to send an SMS. Returns the code only when
  /// the backend runs with DEV_MODE=true (local development).
  Future<String?> requestCode(String phone);

  /// Verifies the code and stores the session. Returns the signed-in profile.
  Future<Profile> verifyCode(String phone, String code);

  /// Restores a stored session, or returns null when the user must sign in.
  Future<Profile?> restore();

  Future<void> logout();

  /// Fires when the stored session can no longer be refreshed.
  Stream<void> get sessionExpired;
}

/// Accepts what people usually type (spaces, dashes, +993 or 8 national digits) and
/// returns +993XXXXXXXX, or null. The backend validates the number again.
String? normalizePhone(String raw) {
  var s = raw.replaceAll(RegExp(r'[\s\-()]'), '');
  if (s.startsWith('00993')) s = '+${s.substring(2)}';
  if (s.startsWith('993') && s.length == 11) s = '+$s';
  if (RegExp(r'^\d{8}$').hasMatch(s)) s = '+993$s';
  if (!RegExp(r'^\+993[67]\d{7}$').hasMatch(s)) return null;
  return s;
}
